fig:barrier-blueprint.source_text:
 egin{figure}[t] \centering  egin{tikzpicture}[ node distance=0.8cm and 1.2cm, auto, block/.style={ rectangle, draw, fill=blue!5, text width=2.2cm, align=center, rounded corners, minimum height=1.0cm, font=\small }, head/.style={ rectangle, draw, fill=yellow!10, text width=1.8cm, align=center, rounded corners, minimum height=0.6cm, font= ootnotesize }, line/.style={ draw, -{Latex[length=2.5mm]}, thick, gray!80 }, barrier/.style={ circle, draw=red!80, fill=red!10, very thick, minimum size=0.6cm, inner sep=0pt }, success/.style={ circle, draw=green!60!black, fill=green!10, very thick, minimum size=0.6cm, inner sep=0pt }, labelnode/.style={ font= fseries\small, anchor=west } ] 
ode[block] (input1) {Input $P_t$\ 	extit{(Global)}}; 
ode[block, right=of input1] (net1) {Single-Head\ Network}; 
ode[barrier, right=of net1] (out1) {\Large $	imes$}; 
ode[right=0.1cm of out1, align=left, font= ootnotesize, text width=2.5cm] {Cannot compute\ global parity\ under FSQI/$\AC^0$}; \path[line] (input1) -- (net1); \path[line] (net1) -- (out1); 
ode[above=0.45cm of input1, labelnode] {(a) Barrier: Single-Frame, Single-Head}; 
ode[block, below=1.3cm of input1] (input2) {Input $(P_{t-1}, P_t)$\ 	extit{(Transition)}}; 
ode[block, right=of input2] (net2) {Single-Head\ Network}; 
ode[success, right=of net2] (out2) {\Large $\checkmark$}; 
ode[right=0.1cm of out2, align=left, font= ootnotesize, text width=2.5cm] {Computes Local\ Difference $\Delta$}; \path[line] (input2) -- (net2); \path[line] (net2) -- (out2); 
ode[above=0.45cm of input2, labelnode] {(b) Bypass 1: Multi-Frame Input}; 
ode[block, below=1.3cm of input2] (input3) {Input $P_t$\ 	extit{(Global)}}; 
ode[right=of input3, text width=0cm, inner sep=0] (split) {}; 
ode[head, right=0.2cm of split, yshift=0.4cm] (head1) {Head $\pi_0$}; 
ode[head, right=0.2cm of split, yshift=-0.4cm] (head2) {Head $\pi_{B-1}$}; 
ode[font= ootnotesize] at ($(head1)!0.5!(head2)$) {$\vdots$}; 
ode[success, right=0.8cm of head1, yshift=-0.4cm] (out3) {\Large $\checkmark$}; 
ode[right=0.1cm of out3, align=left, font= ootnotesize, text width=2.5cm] {Rollout outcomes\ recover $B$ bits}; \path[line] (input3) -- (split); \draw[line] (split.center) |- (head1.west); \draw[line] (split.center) |- (head2.west); \draw[line] (head1.east) -| (out3.north); \draw[line] (head2.east) -| (out3.south); 
ode[above=0.45cm of input3, labelnode] {(c) Bypass 2: Multiple Rollout Heads}; 
ode[block, below=1.3cm of input3] (input4) {Rows of $P_t$\ then $P_{t+1}$}; 
ode[block, right=of input4] (net4) {Recurrent State\ $s\leftarrow s\oplus x_i$}; 
ode[success, right=of net4] (out4) {\Large $\checkmark$}; 
ode[right=0.1cm of out4, align=left, font= ootnotesize, text width=2.5cm] {Nim-sum after\ $N$ row updates\ (growing latency)}; \path[line] (input4) -- (net4); \path[line] (net4) -- (out4); 
ode[above=0.45cm of input4, labelnode] {(d) Bypass 3: Persistent Recurrence}; \end{tikzpicture} \caption{The parity barrier and three structural bypasses. (a) Fixed-latency FSQI inference cannot compute global parity. (b) Two frames expose $\Delta$ for restoration when the predecessor has nim-sum zero. (c) Distinct policy heads recover complementary information through complete rollouts. (d) Persistent recurrence accumulates the nim-sum row by row and retains summaries across positions. Each update has constant depth; the full scan has depth growing with $N$.} \label{fig:barrier-blueprint} \end{figure}

fig:construction-pipeline.source_text:
 egin{figure}[htbp] \centering  egin{tikzpicture}[font=\small, box/.style={draw,rounded corners,align=center,text width=4.1cm,minimum height=1.05cm}, >=Stealth] 
ode[box] (a) {Two frames\$Q=(3,5,6)$, $Q'=(3,4,6)$}; 
ode[box,right=0.5cm of a] (b) {Extract the difference\$\delta=1$}; 
ode[box,right=0.5cm of b] (c) {Propose replacements\$(2,5,7)$}; 
ode[box,below=0.6cm of c] (d) {Test decreases in parallel\$(\mathrm{true},\mathrm{false},\mathrm{false})$}; 
ode[box,left=0.5cm of d] (e) {Select the first candidate\heap $0$, value $2$}; 
ode[box,left=0.5cm of e] (f) {Encode the move\$1\mid00\mid010$}; \draw[->] (a) -- (b); \draw[->] (b) -- (c); \draw[->] (c) -- (d); \draw[->] (d) -- (e); \draw[->] (e) -- (f); \end{tikzpicture} \caption{A schematic of the checked two-frame construction on one legal transition. Boxes group operations, not individual network layers. The general selector also handles multiple candidates, fallback moves and terminal boards.} \label{fig:construction-pipeline} \end{figure}

fig:fsm-shootout-controller.source_text:
 egin{figure}[t] \centering  egin{tikzpicture}[>=Latex, node distance=16mm and 18mm, font=\small] 	ikzset{ state/.style={draw, rounded corners, minimum height=8mm, minimum width=20mm, align=center}, term/.style={draw, rounded corners, thick, minimum height=8mm, minimum width=28mm, align=center}, arrow/.style={->, thick} } 
ode[state] (q0) {$q_0$\ use $\pi_0$}; 
ode[state, right=of q0] (q1) {$q_1$\ use $\pi_1$}; 
ode[inner sep=0pt, right=of q1] (dots) {\Large$\cdots$}; 
ode[state, right=of dots] (qB) {$q_{B-1}$\ use $\pi_{B-1}$}; 
ode[term, above=12mm of dots] (nonzero) {$\sigma(P)
eq 0$\ (declare $N$)}; 
ode[term, below=12mm of qB] (zero) {$\sigma(P)=0$\ (declare $P$)}; \draw[arrow] (q0) -- node[below] {$r_0=0$} (q1); \draw[arrow] (q0) to[bend left=25] node[left] {$r_0=1$} (nonzero); \draw[arrow] (q1) -- node[below] {$r_1=0$} (dots); \draw[arrow] (q1) to[bend left=18] node[above left] {$r_1=1$} (nonzero); \draw[arrow] (dots) -- node[below] {$r_j=0$} (qB); \draw[arrow, dashed] (dots) to[bend left=15] node[above] {$\exists j:\ r_j=1$} (nonzero); \draw[arrow] (qB) to[bend left=15] node[above right] {$r_{B-1}=1$} (nonzero); \draw[arrow] (qB) -- node[right] {$r_{B-1}=0$} (zero); \end{tikzpicture} \caption{A simple finite-state shootout controller for deciding whether $\sigma(P)=\operatorname{nim}(P)$ is zero using the $B$ rollout heads of Proposition~ef{prop:rollout-sufficiency}. The controller queries heads sequentially and halts as soon as it can certify $\sigma(P)
eq 0$. Reaching the final transition to $\sigma(P)=0$ implicitly means $r_0=\cdots=r_{B-1}=0$. } \label{fig:fsm-shootout-controller} \end{figure}

fig:restoration-example.source_text:
 egin{figure}[t] \centering  egin{tikzpicture}[ node distance=1.5cm, auto, font=\small, p_pos/.style={ rectangle, draw=green!50!black, fill=green!5, thick, rounded corners, align=center, text width=2.8cm, minimum height=1.6cm, inner sep=4pt }, n_pos/.style={ rectangle, draw=red!50!black, fill=red!5, thick, rounded corners, align=center, text width=2.8cm, minimum height=1.6cm, inner sep=4pt }, arr/.style={-{Latex[length=2.5mm]}, thick, black!70}, restore_arr/.style={-{Latex[length=2.5mm]}, very thick, blue!80} ] 
ode[p_pos] (Q) { 	extbf{Start ($Q$)}\ Heaps: $\{3, 5, 6\}$\ 	extcolor{green!40!black}{	extbf{nim-sum} $\mathbf{= 0}$} }; 
ode[n_pos, right=2.8cm of Q] (Qp) { 	extbf{After Opponent ($Q'$)}\ Heaps: $\{3, \mathbf{4}, 6\}$\ 	extcolor{red!40!black}{	extbf{nim-sum} $\mathbf{= 1}$} }; 
ode[p_pos, right=2.8cm of Qp] (R) { 	extbf{Restored ($R$)}\ Heaps: $\{\mathbf{2}, 4, 6\}$\ 	extcolor{green!40!black}{	extbf{nim-sum} $\mathbf{= 0}$} }; \draw[arr] (Q) -- node[align=center, above, font= ootnotesize] {Opponent moves\$5 	o 4$} node[align=center, below, font= ootnotesize] {$\delta = 5 \oplus 4 = \mathbf{1}$} (Qp); \draw[restore_arr] (Qp) -- node[align=center, above, font= ootnotesize, text=blue!80] {	extbf{Agent restores}\$3 	o 2$} node[align=center, below, font= ootnotesize, text=blue!80] {Matches $\delta=\mathbf{1}$\$(3 \oplus 2 = 1)$} (R); \end{tikzpicture} \caption{A worked restoration example (three heaps). Starting from a $P$-position $Q$ (green), the opponent changes heap 2 ($5	o 4$), creating a nimber difference $\delta=1$. The agent instantly restores the $P$-position by changing heap 1 ($3	o 2$), which imposes the matching difference $3\oplus 2 = 1$.} \label{fig:restoration-example} \end{figure}

fig:threshold-compilation.source_text:
 egin{figure}[htbp] \centering  egin{tikzpicture}[font=\small, box/.style={draw,rounded corners,align=center,text width=3.1cm,minimum height=1.3cm}, >=Stealth] 
ode[box] (a) {Boolean formulas\depth at most $d$}; 
ode[box,right=0.4cm of a] (b) {Translate gates\OR/NOT: one layer\AND: two layers}; 
ode[box,right=0.4cm of b] (c) {Copy values\to later layers\align dependencies}; 
ode[box,right=0.4cm of c] (d) {Arrange outputs\at most $2d+2$\threshold layers}; \draw[->] (a) -- (b); \draw[->] (b) -- (c); \draw[->] (c) -- (d); \end{tikzpicture} \caption{The checked Boolean-to-threshold compiler, shown schematically. Negated input literals are permitted. AND uses an OR of negated inputs followed by negation, keeping weights and thresholds in $\{0,1\}$. Copying and output stages give a uniform depth bound.} \label{fig:threshold-compilation} \end{figure}
